					this.sampleLine(bullsEyeCorners[1], bullsEyeCorners[2], length),
					this.sampleLine(bullsEyeCorners[2], bullsEyeCorners[3], length),
					this.sampleLine(bullsEyeCorners[3], bullsEyeCorners[0], length)
